//  D. Precision Alignment#include<bits/stdc++.h>using namespace std;int main(){    ios_base::sync_with_stdio(false);    cin.tie(NULL);    int tt;    cin>>tt;    while(tt--){        long long n,k;        cin>>n>>k;        priority_queue<pair<long long,vector<long long>>,vector<pair<long long,vector<long long>>>,greater<pair<long long,vector<long long>>>>pq;        long long tp;        for(long long i=0; i<n; i++){            long long a,b,c;            cin>>a>>b>>c;            if(a==b && a==c){                pq.push({a+b+c,{}});            }            else{                pq.push({a+b+c,{a,b,c,1}});            }        }        while(k>0){            tp=pq.top().first;            vector<long long>tpv=pq.top().second;            pq.pop();            if(tpv.size()==0)break;            long long gg=LLONG_MAX/(1ll*100000);            if(!pq.empty())gg=pq.top().first;            if(tpv[0]>tpv[1] || tpv[0]>tpv[2] || tpv[1]>tpv[2]){                long long diff=(gg-tp)*tpv[3];                if(diff>=k){tp+=k/tpv[3];break;}                else{                    k-=diff;                    if((pq.top().second.size()>0) && (pq.top().second[0]>pq.top().second[1] || pq.top().second[0]>pq.top().second[2] || pq.top().second[1]>pq.top().second[2])){                        pair<long long,vector<long long>>temp=pq.top();                        pq.pop();                        temp.second[3]++;                        pq.push(temp);                    }                    else k-=tpv[3];                    pq.push({pq.top().first+1, tpv});                }            }            else{                if(tpv[1]-tpv[0]<tpv[2]-tpv[1]){                    k-=2*(tpv[1]-tpv[0]+1);                    pq.push({tp-tpv[1]+tpv[0]-1, {3,2,1}});                }                else{                    k-=2*(tpv[2]-tpv[1]+1);                    pq.push({tp-tpv[1]+tpv[0]-1, {3,2,1}});                }            }        }        cout<<tp<<endl;    }    return 0;}